SELECT count(*) FROM public.lineitem lineitem WHERE (NOT EXISTS (SELECT 1 FROM public.part p, public.partsupp ps, public.supplier s, public.orders o, public.nation n WHERE p.p_partkey = lineitem.l_partkey AND ps.ps_partkey = lineitem.l_partkey AND ps.ps_suppkey = lineitem.l_suppkey AND s.s_suppkey = lineitem.l_suppkey AND o.o_orderkey = lineitem.l_orderkey AND n.n_nationkey = s.s_nationkey AND n.n_regionkey = 3 AND o.o_orderdate >= '1995-01-01') OR NOT EXISTS (SELECT 1 FROM public.orders o WHERE o.o_orderkey = lineitem.l_orderkey AND o.o_orderstatus = 'O'));
